  "items": [
    {
      "headline": "Anthropic grants employee-like access to METR for independent safety evaluation",
      "body": "Anthropic has begun providing a team from METR, a nonprofit evaluator, with access to internal tools, systems, and information comparable to its own risk assessment teams, excluding certain sensitive categories. METR will publish its risk assessments independently, with Anthropic able to require redactions only for predefined confidential information. Anthropic is also working with SecureBio, Accenture, and others as evaluators, with varying levels of access and publication rights. The company aims to embed more independent evaluators over time.",
      "sources": ["S1"],
      "relation": "new",
      "updates": null,
      "importance": 1
    },
    {
      "headline": "Anthropic to commit 5% of shares to new Public Benefit Fund, with potential for more as company grows",
      "body": "Anthropic announced it will allocate 5% of its shares to the Anthropic Public Benefit Fund, subject to stockholder approval. The fund, structured as a wholly-owned LLC, may receive an additional 2% of shares for every 50% increase in company value above a set baseline, at the board's discretion. The fund is intended to support projects for societal good, including large donations or direct distributions, and will not be used for lobbying or political giving. Combined with prior commitments, about 20% of Anthropic shares will be dedicated to public benefit if the plan is approved.",
      "sources": ["S3", "S4"],
      "relation": "new",
      "updates": null,
      "importance": 1
    },
    {
      "headline": "Replit makes OpenAI its default AI provider, reducing reliance on Anthropic",
      "body": "Replit CEO Amjad Masad stated that OpenAI's ChatGPT is now the default model on the platform, citing performance, cost, and partnership factors. While Anthropic models remain available, this change is expected to significantly reduce Replit's spend with Anthropic, as most users use the default. Masad said Replit had been a top-five customer of Anthropic until recently. There is disagreement about the current status of the partnership, but Replit continues to offer Anthropic models as an option.",
      "sources": ["S2"],
      "relation": "new",
      "updates": null,
      "importance": 2
    }
  ],
  "left_out": []
}

